forward:
recursive fn make(n:i64)->i64[2]{[n,n+1]}
recursive fn forward(n:i64)->i64[2]{return make(n);}
fn main(){var a:i64[2]=forward(7);assert(a[1]==8);print("forward");}

global:
recursive fn make(n:i64)->i64[2]{[n,n+1]}
var a:i64[2]=make(7);
fn main(){assert(a[1]==8);print("global");}

argument:
recursive fn make(n:i64)->i64[2]{[n,n+1]}
recursive fn read(a:i64[2])->i64{return a[1];}
fn main(){assert(read(make(7))==8);print("argument");}

data:
struct H{items:i64[2]}
recursive fn make(n:i64)->i64[2]{[n,n+1]}
fn main(){var rows:H[]=[H{items:make(7)}];assert(rows[0].items[1]==8);rows[0].items=make(9);assert(rows[0].items[0]==9);print("data");}
